public class ParserEdades {
    public static int parsearEdad(String input) {
        int edad;
        try {
            edad = Integer.parseInt(input);
        } catch (NumberFormatException e) {
            throw new NumberFormatException("Invalid input: " + input);
        }
        if (edad < 0) {
            throw new IllegalArgumentException("Age cannot be negative");
        }
        return edad;
    }

    public static void main(String[] args) {
        String[] entradas = {"25", "abc", "-5", "30"};
        for (String entrada : entradas) {
            try {
                int edad = parsearEdad(entrada);
                System.out.println("Age: " + edad);
            } catch (Exception e) {
                System.out.println("Error: " + e.getMessage());
            }
        }
    }
}

