solution:
public class Validar {
    public static void validarNombre(String nombre) {
        if (nombre == null || nombre.isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty");
        }
    }

    public static void validarEdad(int edad) {
        if (edad < 0 || edad > 150) {
            throw new IndexOutOfBoundsException("Age must be between 0 and 150");
        }
    }

    public static void validarEmail(String email) {
        if (email == null) {
            throw new NullPointerException("Email cannot be null");
        }
        if (!email.contains("@")) {
            throw new ArithmeticException("Email must contain '@'");
        }
    }

    public static void validarTodo(String nombre, int edad, String email) {
        try {
            validarNombre(nombre);
        } catch (IllegalArgumentException e) {
            System.out.println("Name error: " + e.getMessage());
        }
        try {
            validarEdad(edad);
        } catch (IndexOutOfBoundsException e) {
            System.out.println("Age error: " + e.getMessage());
        }
        try {
            validarEmail(email);
        } catch (NullPointerException e) {
            System.out.println("Email error: " + e.getMessage());
        } catch (ArithmeticException e) {
            System.out.println("Email error: " + e.getMessage());
        }
    }

    public static void main(String[] args) {
        validarTodo("", 200, "test");
        System.out.println("---");
        validarTodo("Ana", 25, "ana@mail.com");
    }
}
